// DecodeError identifies and decodes a declared custom error.
func (c *DiesisPrivacyPoolsBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("AlreadyRegistered()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeAlreadyRegisteredError(raw)
	}
	if definition, err := c.customError("InvalidProofLength()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidProofLengthError(raw)
	}
	if definition, err := c.customError("InvalidVerifierIdentity()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidVerifierIdentityError(raw)
	}
	if definition, err := c.customError("NonCanonicalField()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNonCanonicalFieldError(raw)
	}
	if definition, err := c.customError("NotInitialized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotInitializedError(raw)
	}
	if definition, err := c.customError("NotPendingOwner()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotPendingOwnerError(raw)
	}
	if definition, err := c.customError("NotRegisteredProvider()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotRegisteredProviderError(raw)
	}
	if definition, err := c.customError("RootMismatch()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRootMismatchError(raw)
	}
	if definition, err := c.customError("Unauthorized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeUnauthorizedError(raw)
	}
	if definition, err := c.customError("ZeroAddress()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAddressError(raw)
	}
	if definition, err := c.customError("ZeroNullifier()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroNullifierError(raw)
	}
	if definition, err := c.customError("ZeroRoot()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroRootError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
